var calc_output = [];

var trauma = parseFloat(trauma);
var immobilization = parseFloat(immobilization);
var age = parseFloat(age);
var sex = parseFloat(sex);
var bmi = parseFloat(bmi);
var fam_hx = parseFloat(fam_hx);
var hx = parseFloat(hx);
var oc = parseFloat(oc);
var cancer = parseFloat(cancer);
var preg = parseFloat(preg);
var other = parseFloat(other);
var surgery = parseFloat(surgery);
var como = parseFloat(como);
var veins = parseFloat(veins);

var score = trauma + immobilization + age + sex + bmi + fam_hx + hx + oc + cancer + preg + other + surgery + como + veins;

var risk;
if (score < 7) {
    risk = 'Low';
} else {
    risk = 'High';
}

var x = -6.677015 + 0.3332203*score;
var risk_perc = (Math.exp(x)/(1 + Math.exp(x)))*100;

calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: risk + ' (' + risk_perc.toFixed(1) + '%) 3-month risk of VTE'
});
calc_output.push({
    name: '10516_TRiP(cast) Score_result (score)',
    value: score,
    value_text: 'points',
    message: 'TRiP(cast) Score'
});
calc_output.push({
    name: '10516_TRiP(cast) Score_result (risk)',
    value: risk_perc.toFixed(1),
    value_text: '%',
    message: risk + ' 3-month risk of VTE'
});
